import {SESSIONS,WorkoutTimer,dateKey,addMonths,daysBetween,formatTime,freshState,validateState,validDate,weeklySummary} from './engine.js';
import {StateStore} from './storage.js';
import {CHECKPOINT_KEY,checkpointFor,validateCheckpoint,restoreCheckpoint} from './checkpoint.js';
import {EXERCISES,SOURCES,movementArt} from './exercises.js';
const $=id=>document.getElementById(id);
const icons={activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h3m4 0h3"/>',play:'<circle cx="12" cy="12" r="9"/><path d="m10 8 6 4-6 4z"/>','play-fill':'<path d="m8 5 11 7-11 7z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',chart:'<path d="M4 4v16h17M7 15l4-5 4 2 5-7"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',volume:'<path d="M4 9v6h4l5 4V5L8 9zM17 8q5 4 0 8m2-11q8 7 0 14"/>',muted:'<path d="M4 9v6h4l5 4V5L8 9zM17 9l5 6m0-6-5 6"/>',reset:'<path d="M3 5v5h5M4 10a8 8 0 1 1 1 8"/>',skip:'<path d="m4 5 11 7L4 19zM19 5v14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',leaf:'<path d="M20 3C5 3 1 9 5 16s15 1 15-13ZM5 21c0-6 5-10 10-13"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',check:'<path d="m5 12 5 5L20 7"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.activity}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const STORAGE='form-seven.v1';
const store=new StateStore({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},STORAGE);
let state=store.load(validateState,freshState),storageFailed=store.locked,loadMessage='',migrated=false;
if(store.locked)loadMessage='Previous data needs recovery. Saving is paused to preserve the original records.';
else if(store.raw){try{const previous=JSON.parse(store.raw);migrated=previous.version===1;if(migrated&&previous.profile.goalLoss===30)loadMessage='Your initial goal is now 10 kg over seven months. Your history has been kept.';}catch{}}
const newId=()=>globalThis.crypto?.randomUUID?.()??'entry-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const timer=new WorkoutTimer();
let pendingCheckpoint=null,checkpointStamp=0;
try{const raw=localStorage.getItem(CHECKPOINT_KEY);if(raw)pendingCheckpoint=validateCheckpoint(JSON.parse(raw));}catch{try{localStorage.removeItem(CHECKPOINT_KEY);}catch{}}
function persistWorkout(){if(pendingCheckpoint)return;try{const draft=checkpointFor(timer);if(!draft){localStorage.removeItem(CHECKPOINT_KEY);return;}const now=Date.now();if(timer.status==='running'&&now-checkpointStamp<1000)return;localStorage.setItem(CHECKPOINT_KEY,JSON.stringify(draft));checkpointStamp=now;}catch{}}

let lastIndex=-1,completionRecorded=false,audioCtx=null,wakeLock=null,lastView='workout',filter='all',toastHandle;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('toast').classList.remove('visible'),5500);}
function save(){try{store.save(state);storageFailed=false;document.documentElement.dataset.unsavedChanges='false';return true;}catch(e){storageFailed=true;document.documentElement.dataset.unsavedChanges='true';toast(store.locked?'Saving is paused. Recover your original records or restore a backup first.':'Your browser could not save this change. Export a backup to keep your entries.');return false;}}
function shortDate(key){return new Date(key+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function weekRange(){const now=new Date(),day=(now.getDay()+6)%7;const start=new Date(now.getFullYear(),now.getMonth(),now.getDate()-day);return {start:dateKey(start),end:dateKey(now),startDate:start};}
function showView(name,updateHash=true){if(!['workout','plan','library','progress'].includes(name))name='workout';lastView=name;document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!=='view-'+name);document.querySelectorAll('[data-view]').forEach(e=>{const selected=e.dataset.view===name;e.classList.toggle('active',selected);if(selected)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});const titles={workout:'WORKOUT',plan:'YOUR PLAN',library:'EXERCISE LIBRARY',progress:'PROGRESS'};$('breadcrumb').textContent='YOUR TRAINING SPACE / '+titles[name];if(updateHash){try{history.replaceState(null,'','#'+name);}catch{if(location.hash!=='#'+name)location.hash=name;}}if(name!=='workout'&&timer.status==='running'){timer.pause();releaseWakeLock();renderTimer();toast('Workout paused. Return to your workout to resume.');}window.scrollTo({top:0,behavior:'instant'});}
function weeklyStats(){const {start,end}=weekRange();return weeklySummary(state,start,end);}
function renderJourney(){
  const p=state.profile,today=dateKey(),days=Math.max(0,daysBetween(p.startDate,today)),total=daysBetween(p.startDate,p.deadline),pct=Math.max(0,Math.min(100,days/total*100));
  $('journey-fill').style.width=pct+'%';
  $('journey-caption').textContent=daysBetween(today,p.startDate)>0?'Begins '+shortDate(p.startDate):`Day ${days+1} of your journey`;
  $('day-number').textContent=String(days+1).padStart(2,'0');
  $('sidebar-goal').firstChild.textContent=p.startWeight===null?'Set up your goal ':'Review your goal ';
  const rate=p.goalLoss/(total/7);
  $('plan-loss').textContent=p.goalLoss;
  $('pace-copy').textContent=`Your initial target averages ${rate.toFixed(2)} kg per week across the whole plan. ${rate>1.05?'This is faster than usual gradual-loss guidance. Consider a longer timeline and review it with a clinician or dietitian.':rate>=.85?'This is near the upper end of usual gradual-loss guidance. Review the pace with a clinician or dietitian.':'Weekly changes will vary. Review your progress after the first 5 kg, then reassess before setting your next goal.'}`;
  $('initial-target-note').textContent=p.startWeight===null?'The 10 kg starting goal assumes a weight around 100 kg. Enter your current weight in My goal and review whether this target fits you.':`At your starting weight of ${p.startWeight.toFixed(1)} kg, 5–10% is ${(p.startWeight*.05).toFixed(1)}–${(p.startWeight*.10).toFixed(1)} kg. Use this as context when reviewing your initial target.`;
}
function renderWeek(){const {startDate}=weekRange(),today=dateKey(),w=weeklyStats();$('weekly-sessions').textContent=w.complete.length;$('week-days').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(startDate);d.setDate(d.getDate()+i);const key=dateKey(d),done=w.complete.some(x=>x.date===key);return `<div class="week-day ${key===today?'today':''} ${done?'done':''}" title="${shortDate(key)}${done?': workout completed':''}">${['M','T','W','T','F','S','S'][i]}<span>${done?'✓':d.getDate()}</span></div>`;}).join('');$('weekly-strength-days').textContent=w.strengthDays;$('weekly-brisk-minutes').textContent=w.briskMinutes;$('weekly-walk-fill').style.width=Math.min(100,w.briskMinutes/150*100)+'%';$('weekly-strength-fill').style.width=Math.min(100,w.strengthDays/2*100)+'%';}
function renderLineup(){const s=SESSIONS[timer.id];document.querySelectorAll('[data-session]').forEach(b=>b.classList.toggle('selected',b.dataset.session===timer.id));$('rounds-summary').textContent=`${s.rounds} rounds · ${s.work}s work / ${s.rest}s rest`;$('lineup').innerHTML=s.exercises.map(id=>{const ex=EXERCISES[id];return `<div class="lineup-item"><span class="lineup-icon">${movementArt(ex.art)}</span><div class="exercise-info"><strong>${ex.name}</strong><small>${ex.subtitle}</small></div><span class="duration">${s.work} sec</span><button class="lineup-watch" data-demo="${id}" aria-label="Watch ${ex.name} demo">${icon('play')}</button></div>`;}).join('');$('session-description').textContent=s.description+' Work at a controlled pace; the time is an activity window, not a repetition target.';}
function stepTitle(step){return step.label||EXERCISES[step.exercise].name;}
function renderStep(){const step=timer.step,ex=EXERCISES[step.exercise],s=SESSIONS[timer.id];$('movement-art').innerHTML=movementArt(ex.art);$('visual-name').textContent=step.type==='cooldown'?'Easy walking':ex.name;$('visual-index').textContent=step.round?String(s.exercises.indexOf(step.exercise)+1).padStart(2,'0'):'01';$('phase-badge').textContent={warmup:'WARM-UP',work:'WORK INTERVAL',rest:'RECOVERY',cooldown:'COOL-DOWN'}[step.type];$('round-label').textContent=step.round?`Round ${step.round} of ${s.rounds}`:step.type==='warmup'?'Ease into the session':'Bring your pace down';$('exercise-title').textContent=stepTitle(step);$('exercise-time').textContent=step.duration>=60?`${step.duration/60} min`:`${step.duration} sec`;$('exercise-description').textContent=step.type==='rest'?'Relax, breathe and reset. Take longer if you need it—pause the timer at any point.':step.type==='warmup'?'Begin with easy marching and relaxed shoulder movements. Let the pace build gently. Use “Add 1 min” if you need more warm-up time.':ex.description;$('exercise-cues').innerHTML=(step.type==='rest'?['Relax your shoulders','Take a comfortable breath','Pause for more recovery']:ex.cues).map(t=>`<span class="cue">${t}</span>`).join('');$('demo-provider').textContent=ex.shortProvider+' · Video';$('watch-current').hidden=step.type==='rest'||step.type==='cooldown';$('announcer').textContent=stepTitle(step)+', '+formatTime(step.duration);lastIndex=timer.index;}
function renderTimer(){document.documentElement.dataset.workoutStatus=pendingCheckpoint?'paused':timer.status;persistWorkout();if(lastIndex!==timer.index)renderStep();const step=timer.step;$('remaining').textContent=formatTime(timer.remaining);$('elapsed').innerHTML=`${formatTime(Math.floor(timer.elapsed))} <small>/ ${formatTime(timer.total)}</small>`;$('interval-label').textContent=timer.status==='complete'?'FINISHED':step.type==='rest'?'REST':step.type==='warmup'?'WARM-UP':step.type==='cooldown'?'COOL-DOWN':`ROUND ${step.round} / ${SESSIONS[timer.id].rounds}`;$('timer-status').textContent={ready:'READY WHEN YOU ARE',running:'YOU ARE DOING THE WORK',paused:'PAUSED · TAKE YOUR TIME',complete:'SESSION FINISHED'}[timer.status];$('start-label').textContent={ready:'Start workout',running:'Pause',paused:'Resume',complete:'Start again'}[timer.status];$('start-timer').firstElementChild.innerHTML=icon(timer.status==='running'?'pause':'play-fill');$('ring-value').style.strokeDashoffset=String(678.584*(1-timer.remaining/step.duration));$('session-fill').style.width=timer.position/timer.total*100+'%';const next=timer.steps[timer.index+1];$('next-label').textContent=next?`${stepTitle(next)} · ${next.duration>=60?next.duration/60+' min':next.duration+' sec'}`:'You did it. Time to recover.';$('next-interval').disabled=timer.status==='ready'||timer.status==='complete';$('toggle-sound').innerHTML=icon(state.sound?'volume':'muted');$('toggle-sound').setAttribute('aria-label',state.sound?'Turn timer sound off':'Turn timer sound on');$('toggle-sound').setAttribute('aria-pressed',String(state.sound));const warmButton=$('extend-warmup');warmButton.disabled=timer.index!==0||timer.status==='complete'||timer.steps[0].duration>=360;warmButton.textContent=timer.steps[0].duration>=360?'Warm-up extended · 6+ min':'Add warm-up time +';const add=$('add-minute');if(add){add.hidden=!['warmup','rest','cooldown'].includes(step.type)||timer.status==='complete';add.textContent=step.type==='rest'?'+ 30 sec recovery':'+ 1 min';}if(timer.status==='complete'&&!completionRecorded)recordCompletion();}
async function acquireWakeLock(){try{if('wakeLock'in navigator)wakeLock=await navigator.wakeLock.request('screen');}catch(e){/* Browsers may decline; timing still works while visible. */}}
function releaseWakeLock(){if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null;}}
function enableAudio(){try{if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});}catch(e){audioCtx=null;}}
function beep(finish=false){if(!state.sound||!audioCtx)return;try{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=finish?660:520;g.gain.setValueAtTime(.06,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.22);o.start();o.stop(audioCtx.currentTime+.23);}catch(e){}}
function resetTimer(id=timer.id){timer.reset(id);lastIndex=-1;completionRecorded=false;releaseWakeLock();renderLineup();renderTimer();}
function recordCompletion(){completionRecorded=true;releaseWakeLock();beep(true);const actual=Math.round(timer.elapsed),hasActivity=actual>=1;let saved=false;if(hasActivity){state.workouts.push({id:newId(),date:dateKey(),session:timer.id,seconds:actual,skipped:timer.skipped});saved=save();}renderProgress();renderWeek();$('complete-title').textContent=timer.skipped?'Your movement counts.':'One day stronger.';$('complete-copy').textContent=hasActivity&&!saved?'Your session is visible here, but could not be saved on this device. Export a backup from Your progress before closing.':timer.skipped?`${timer.skipped} interval${timer.skipped===1?' was':'s were'} skipped. ${saved?'Only actual activity time was logged as a partial session.':'No activity time was logged.'}`:'You completed every interval. Your session has been added to your progress.';$('complete-time').textContent=formatTime(actual);$('complete-name').textContent=SESSIONS[timer.id].title;$('complete-dialog').showModal();}
function videoFor(id){
  const ex=EXERCISES[id];if(!ex)return;pauseForDialog();
  $('video-title').textContent=ex.name;$('video-player').replaceChildren();
  if(location.protocol==='file:'||!navigator.onLine){
    const panel=document.createElement('div');panel.className='local-video-card';
    panel.innerHTML=movementArt(ex.art);
    const text=document.createElement('p');text.textContent=navigator.onLine?'This local copy opens the original video in a new tab. Your workout is paused.':'Video demos need internet. Use the illustration and form cues below while offline. Your workout is paused.';
    const link=document.createElement('a');link.href='https://www.youtube.com/watch?v='+ex.video;link.target='_blank';link.rel='noopener noreferrer';link.className='light-btn';link.textContent='Watch demo on YouTube ↗';
    panel.append(text,link);$('video-player').append(panel);
  }else{
    const frame=document.createElement('iframe');frame.src=`https://www.youtube-nocookie.com/embed/${ex.video}?rel=0&playsinline=1`;frame.title=ex.name+' demonstration by '+ex.provider;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';$('video-player').append(frame);
  }
  $('video-credit').textContent='Video credit: '+ex.provider;$('video-source').href=ex.source;$('video-youtube').href='https://www.youtube.com/watch?v='+ex.video;
  $('video-cues').innerHTML=ex.cues.map(t=>`<span class="cue">${t}</span>`).join('');$('video-dialog').showModal();
}
function renderLibrary(){const query=$('exercise-search').value.trim().toLowerCase();const list=Object.values(EXERCISES).filter(e=>e.id!=='cool'&&(filter==='all'||e.category===filter)&&(e.name+' '+e.subtitle+' '+e.provider).toLowerCase().includes(query));$('library-grid').innerHTML=list.length?list.map(e=>`<article class="library-card"><button class="library-thumb" data-demo="${e.id}" aria-label="Watch ${e.name} demonstration">${movementArt(e.art)}<img src="https://i.ytimg.com/vi/${e.video}/hqdefault.jpg" alt="" loading="lazy" referrerpolicy="no-referrer"><span class="thumb-play">${icon('play-fill')}</span><span class="subtle-pill">${e.category==='standing'?'STANDING':'CORE & FLOOR'}</span></button><div class="library-body"><h2>${e.name}</h2><p>${e.subtitle}<br>${e.shortProvider}</p><button class="text-btn" data-demo="${e.id}">Watch demonstration ↗</button></div></article>`).join(''):'<p class="empty-results">No moves match your search. Try another name or choose All moves.</p>';$('library-grid').querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>img.remove()));}
function sortedWeights(){return [...state.weights].sort((a,b)=>a.date.localeCompare(b.date));}
function chartData(){const w=sortedWeights();if(state.profile.startWeight!==null&&!w.some(x=>x.date===state.profile.startDate))w.push({date:state.profile.startDate,weight:state.profile.startWeight});return w.sort((a,b)=>a.date.localeCompare(b.date));}
function renderChart(){const data=chartData();if(!data.length){$('weight-chart').innerHTML=`<div class="chart-empty">${icon('chart')}<strong>Your story starts with one entry.</strong><p>Add your starting weight or log a weigh-in to see your trend here.</p><button class="text-btn" id="chart-add">Log your first weight ↗</button></div>`;return;}const target=state.profile.startWeight===null?null:state.profile.startWeight-state.profile.goalLoss;const vals=data.map(d=>d.weight);if(target!==null)vals.push(target);const min=Math.floor((Math.min(...vals)-2)/2)*2,max=Math.ceil((Math.max(...vals)+2)/2)*2;const width=620,height=245,pad={left:43,right:24,top:15,bottom:38};const first=data[0].date,last=data[data.length-1].date,span=daysBetween(first,last)||1;const x=key=>data.length===1?width/2:pad.left+daysBetween(first,key)/span*(width-pad.left-pad.right),y=n=>pad.top+(max-n)/(max-min)*(height-pad.top-pad.bottom);const grid=Array.from({length:5},(_,i)=>{const n=min+(max-min)*i/4;return `<line x1="${pad.left}" y1="${y(n)}" x2="${width-pad.right}" y2="${y(n)}" stroke="#e5ecd9"/><text x="${pad.left-9}" y="${y(n)+4}" text-anchor="end" class="chart-label">${n.toFixed(0)}</text>`;}).join('');const path=data.map((d,i)=>`${i?'L':'M'}${x(d.date)},${y(d.weight)}`).join(' ');const dots=data.map(d=>`<circle cx="${x(d.date)}" cy="${y(d.weight)}" r="4" fill="#76974d" stroke="white" stroke-width="2"><title>${shortDate(d.date)}: ${d.weight} kg</title></circle>`).join('');const goal=target===null?'':`<line x1="${pad.left}" y1="${y(target)}" x2="${width-pad.right}" y2="${y(target)}" stroke="#bacb9d" stroke-dasharray="5 5"/><text x="${width-pad.right}" y="${y(target)-7}" text-anchor="end" class="chart-label">Your target: ${target.toFixed(1)} kg</text>`;$('weight-chart').innerHTML=`<svg class="weight-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Weight history, ${data.length} entries. Latest ${data[data.length-1].weight} kilograms. Full entries are listed below.">${grid}${goal}<path d="${path}" fill="none" stroke="#799c4f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${dots}<text x="${pad.left}" y="${height-9}" class="chart-label">${shortDate(first)}</text>${data.length>1?`<text x="${width-pad.right}" y="${height-9}" text-anchor="end" class="chart-label">${shortDate(last)}</text>`:''}</svg>`;}
function renderProgress(){const weights=sortedWeights(),latest=weights.at(-1),start=state.profile.startWeight,w=weeklyStats();$('metric-weight').innerHTML=(latest?latest.weight.toFixed(1):start===null?'—':start.toFixed(1))+'<small>kg</small>';$('metric-weight-note').textContent=latest?'Logged '+shortDate(latest.date):start===null?'Add your first weigh-in':'Your starting weight';const lost=latest&&start!==null?start-latest.weight:null;$('metric-loss').innerHTML=(lost===null?'—':Math.abs(lost).toFixed(1))+'<small>kg</small>';$('metric-loss-note').textContent=lost===null?'Set a starting weight and log an entry':lost>0?'Below your starting weight':lost<0?'Above your starting weight':'No change from your starting weight';$('metric-workouts').textContent=state.workouts.filter(x=>x.skipped===0).length;$('metric-minutes').innerHTML=w.minutes+'<small>min</small>';$('goal-start').textContent=start===null?'—':start.toFixed(1);$('goal-end').textContent=start===null?'—':(start-state.profile.goalLoss).toFixed(1);const percent=lost===null?0:Math.max(0,Math.min(100,lost/state.profile.goalLoss*100));$('goal-fill').style.width=percent+'%';$('goal-status').textContent=start===null?'Set a starting weight to follow your goal.':lost===null?'Log a weigh-in to see how your weight changes.':`${percent.toFixed(0)}% of your personal weight-loss target. Progress is rarely a straight line.`;$('goal-start-date').textContent=shortDate(state.profile.startDate);$('goal-deadline').textContent=shortDate(state.profile.deadline);const waistEntries=weights.filter(w=>w.waist!==undefined),lastWaist=waistEntries.at(-1);$('waist-summary').hidden=!lastWaist;$('waist-summary').textContent=lastWaist?'Latest waist: '+lastWaist.waist.toFixed(1)+' cm · '+shortDate(lastWaist.date):'';renderChart();$('weight-history').innerHTML=weights.length?[...weights].reverse().map(w=>`<div class="history-row"><div><strong>${shortDate(w.date)}</strong>${w.waist!==undefined?`<small>Waist: ${w.waist.toFixed(1)} cm</small>`:''}</div><span>${w.weight.toFixed(1)} kg</span><button data-delete-weight="${w.date}" aria-label="Delete weight entry for ${shortDate(w.date)}">×</button></div>`).join(''):'<p class="history-empty">No weigh-ins yet.<br>Add one when you are ready.</p>';const activities=[...state.workouts.map(w=>({...w,kind:'workout'})),...state.walks.map(w=>({...w,kind:'walk'}))].sort((a,b)=>b.date.localeCompare(a.date));$('activity-history').innerHTML=activities.length?activities.slice(0,30).map(w=>`<div class="history-row"><div><strong>${w.kind==='walk'?(w.intensity==='brisk'?'Brisk walking':w.intensity==='easy'?'Easy walking':'Walking'):SESSIONS[w.session].title}</strong><small>${shortDate(w.date)}${w.kind==='workout'&&w.skipped?' · Partial session':''}</small></div><span>${w.kind==='walk'?w.minutes+' min':formatTime(w.seconds)}</span><button data-delete-activity="${w.id}" data-kind="${w.kind}" aria-label="Delete this activity entry">×</button></div>`).join(''):'<p class="history-empty">Finish a workout or log a walk.<br>Your activity will appear here.</p>';}
function pauseForDialog(){if(timer.status==='running'){timer.pause();releaseWakeLock();renderTimer();}}
function openGoal(){pauseForDialog();const p=state.profile;$('goal-weight-input').value=p.startWeight??'';$('goal-loss-input').value=p.goalLoss;$('goal-start-input').value=p.startDate;$('goal-date-input').value=p.deadline;$('goal-error').textContent='';pacePreview();$('goal-dialog').showModal();}
function pacePreview(){const start=$('goal-start-input').value,end=$('goal-date-input').value,loss=Number($('goal-loss-input').value);const days=daysBetween(start,end);$('goal-pace-preview').textContent=days>0&&loss>0?`This target averages ${(loss/(days/7)).toFixed(2)} kg per week. Weekly changes can be uneven. An initial 5–10% loss over about six months is a common starting goal; the default here is 10 kg over seven months. Review it as you progress.`:'Choose a target date after your starting date.';}
function openWeight(){pauseForDialog();$('weight-date').value=dateKey();$('weight-date').max=dateKey();$('weight-value').value='';$('waist-value').value='';$('weight-error').textContent='';$('weight-dialog').showModal();}
function openWalk(){pauseForDialog();$('walk-date').value=dateKey();$('walk-date').max=dateKey();$('walk-minutes').value=10;$('walk-brisk').checked=false;$('walk-error').textContent='';$('walk-dialog').showModal();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]'),go=e.target.closest('[data-go]'),demo=e.target.closest('[data-demo]'),close=e.target.closest('[data-close]'),session=e.target.closest('[data-session]'),f=e.target.closest('[data-filter]'),delW=e.target.closest('[data-delete-weight]'),delA=e.target.closest('[data-delete-activity]');if(nav)showView(nav.dataset.view);if(go)showView(go.dataset.go);if(demo)videoFor(demo.dataset.demo);if(close)$(close.dataset.close).close();if(session){if(session.dataset.session===timer.id)return;if(timer.elapsed>0&&timer.status!=='complete'&&!confirm('Switch workouts? The current unfinished session will be reset.'))return;resetTimer(session.dataset.session);}if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===f));renderLibrary();}if(delW&&confirm('Delete this weigh-in?')){state.weights=state.weights.filter(w=>w.date!==delW.dataset.deleteWeight);const saved=save();renderProgress();if(saved)toast('Weigh-in deleted.');}if(delA&&confirm('Delete this activity entry?')){const field=delA.dataset.kind==='walk'?'walks':'workouts';state[field]=state[field].filter(w=>w.id!==delA.dataset.deleteActivity);const saved=save();renderProgress();renderWeek();if(saved)toast('Activity deleted.');}if(e.target.closest('#chart-add'))openWeight();});
$('start-timer').addEventListener('click',()=>{if(pendingCheckpoint){toast('Resume or discard your saved session first.');return;}enableAudio();if(timer.status==='running'){timer.pause();releaseWakeLock();}else{if(timer.status==='complete')resetTimer();timer.start();acquireWakeLock();}renderTimer();});
$('reset-timer').addEventListener('click',()=>{if(timer.elapsed>0&&timer.status!=='complete'&&!confirm('Reset this workout? Your unfinished session will not be logged.'))return;resetTimer();});
$('next-interval').addEventListener('click',()=>{timer.next();beep();renderTimer();if(timer.status!=='complete')toast('Interval skipped. This will be logged as a partial session.');});
$('toggle-sound').addEventListener('click',()=>{state.sound=!state.sound;if(state.sound)enableAudio();save();renderTimer();});
$('watch-current').addEventListener('click',()=>videoFor(timer.step.exercise));
$('video-dialog').addEventListener('close',()=>$('video-player').replaceChildren());
$('exercise-search').addEventListener('input',renderLibrary);
['open-goal','sidebar-goal','edit-goal-plan','edit-goal-progress'].forEach(id=>$(id).addEventListener('click',openGoal));
['add-weight','add-weight-inline'].forEach(id=>$(id).addEventListener('click',openWeight));
$('log-walk').addEventListener('click',openWalk);
$('plan-log-walk').addEventListener('click',openWalk);
$('use-recommended-goal').addEventListener('click',()=>{$('goal-loss-input').value=10;const start=$('goal-start-input').value;if(validDate(start))$('goal-date-input').value=addMonths(start,7);pacePreview();});
['goal-start-input','goal-date-input','goal-loss-input'].forEach(id=>$(id).addEventListener('input',pacePreview));
$('goal-form').addEventListener('submit',e=>{e.preventDefault();const weight=$('goal-weight-input').value.trim();const next={...state,profile:{startWeight:weight===''?null:Number(weight),goalLoss:Number($('goal-loss-input').value),startDate:$('goal-start-input').value,deadline:$('goal-date-input').value}};try{state=validateState(next);const ok=save();$('goal-dialog').close();renderJourney();renderProgress();if(ok)toast('Your goal has been saved.');}catch(err){$('goal-error').textContent=err.message;}});
$('weight-form').addEventListener('submit',e=>{
  e.preventDefault();const date=$('weight-date').value,weight=Number($('weight-value').value),waistText=$('waist-value').value.trim(),waist=waistText===''?null:Number(waistText);
  if(!validDate(date)||date>dateKey()||!Number.isFinite(weight)||weight<30||weight>400||(waist!==null&&(!Number.isFinite(waist)||waist<30||waist>250))){$('weight-error').textContent='Enter a date up to today, a weight between 30 and 400 kg, and an optional waist measurement between 30 and 250 cm.';return;}
  const existing=state.weights.find(w=>w.date===date),entry={date,weight};
  if(waist!==null)entry.waist=waist;else if(existing?.waist!==undefined)entry.waist=existing.waist;
  state.weights=state.weights.filter(w=>w.date!==date);state.weights.push(entry);const ok=save();$('weight-dialog').close();renderProgress();if(ok)toast('Weigh-in saved. One entry is only part of your story.');
});
$('walk-form').addEventListener('submit',e=>{e.preventDefault();const date=$('walk-date').value,minutes=Number($('walk-minutes').value);if(!validDate(date)||date>dateKey()||!Number.isInteger(minutes)||minutes<1||minutes>300){$('walk-error').textContent='Enter a date up to today and 1–300 whole minutes.';return;}state.walks.push({id:newId(),date,minutes,intensity:$('walk-brisk').checked?'brisk':'easy'});const ok=save();$('walk-dialog').close();renderProgress();renderWeek();if(ok)toast('Walk logged. Your everyday movement counts.');});
$('finish-workout').addEventListener('click',()=>{$('complete-dialog').close();showView('progress');});
$('export-data').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`form-seven-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup prepared. Keep the downloaded file somewhere safe.');});
$('import-data').addEventListener('click',()=>$('import-file').click());
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw new Error('Choose a backup file smaller than 3 MB.');const incoming=validateState(JSON.parse(await file.text()));if(!confirm('Restore this backup? It replaces the progress currently saved in this browser.'))return;store.replace(incoming);state=incoming;storageFailed=false;document.documentElement.dataset.unsavedChanges='false';const ok=true;$('data-recovery').hidden=true;renderJourney();renderProgress();renderWeek();renderTimer();if(ok)toast('Your backup has been restored.');}catch(err){toast('Could not restore: '+err.message);}finally{e.target.value='';}});
document.addEventListener('visibilitychange',()=>{persistWorkout();if(document.hidden&&timer.status==='running'){timer.pause();releaseWakeLock();renderTimer();toast('Workout paused while this tab was away. Press Resume when ready.');}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&lastView==='workout'&&!document.querySelector('dialog[open]')&&!e.target.closest('input,button,textarea,select,a,[contenteditable]')){e.preventDefault();$('start-timer').click();}});
window.addEventListener('hashchange',()=>showView(location.hash.slice(1),false));
window.addEventListener('beforeunload',e=>{if(timer.status==='running'||timer.status==='paused'){e.preventDefault();e.returnValue='';}});
const addMinute=document.createElement('button');addMinute.id='add-minute';addMinute.className='extra-time-btn';addMinute.textContent='+ 1 min';$('timer-status').after(addMinute);addMinute.addEventListener('click',()=>{if(timer.status==='running'){timer.tick();renderTimer();}const step=timer.step,extra=step.type==='rest'?30:60;if(!['rest','warmup','cooldown'].includes(step.type)||timer.status==='complete')return;if(timer.total+extra>3600){toast('Pause the timer for any further recovery.');return;}step.duration+=extra;timer.remaining+=extra;lastIndex=-1;renderTimer();toast(step.type==='rest'?'Extra recovery added.':'An extra minute has been added.');});
$('extend-warmup').addEventListener('click',()=>{if(timer.index!==0||timer.status==='complete')return;const extra=Math.max(0,360-timer.steps[0].duration);timer.steps[0].duration+=extra;timer.remaining+=extra;lastIndex=-1;renderTimer();toast('Warm-up extended. Total session: '+formatTime(timer.total)+'.');});
$('source-links').innerHTML=SOURCES.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a></li>`).join('');
$('today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
function downloadText(text,name){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('data-recovery').hidden=!store.locked;$('export-original').hidden=store.raw===null;
$('export-original').addEventListener('click',()=>downloadText(store.raw||'',`form-seven-original-${dateKey()}.json`));
$('recover-import').addEventListener('click',()=>$('import-file').click());
$('reset-local').addEventListener('click',()=>{if(!confirm('Reset all local progress? Download your original records first. This cannot be undone.'))return;try{const clean=freshState();store.replace(clean);state=clean;storageFailed=false;$('data-recovery').hidden=true;renderJourney();renderProgress();renderWeek();toast('Local records reset.');}catch{toast('Your browser could not reset these records.');}});
if(pendingCheckpoint){$('workout-recovery').hidden=false;$('workout-recovery-copy').textContent=`You have an unfinished ${SESSIONS[pendingCheckpoint.id].title} session. Resume from ${formatTime(pendingCheckpoint.elapsed)} elapsed, or discard it.`;}
$('resume-saved').addEventListener('click',()=>{if(!pendingCheckpoint)return;restoreCheckpoint(timer,pendingCheckpoint);pendingCheckpoint=null;completionRecorded=false;lastIndex=-1;$('workout-recovery').hidden=true;renderLineup();renderTimer();showView('workout');toast('Session restored paused. Press Resume when you are ready.');});
$('discard-saved').addEventListener('click',()=>{if(!confirm('Discard the unfinished saved session?'))return;pendingCheckpoint=null;$('workout-recovery').hidden=true;resetTimer();});
renderJourney();renderWeek();renderLineup();renderTimer();renderLibrary();renderProgress();showView(location.hash.slice(1)||'workout',false);
setInterval(()=>{if(timer.status==='running'){const events=timer.tick();if(events.includes('interval'))beep();renderTimer();}},100);
if(migrated)save();
if(loadMessage)setTimeout(()=>toast(loadMessage),300);
